--[[
	GONARCH (Black Mesa) - Plane Crazy SmallPart build  -  1:1 desde el GLB "black_mesa_gonarch_rig"
	===== SHARED FIGURE DEFINITION =====
	IDENTICO en el script 1 (pintar/tamaños) y en el script 2 (animar). 1700 SmallParts.
	Las placas estan ajustadas sobre la malla real (posicion, inclinacion, tamaño y color muestreado de la textura)
	y cada una va pegada a su hueso del rig original (26 huesos con pesos).
	SCALE = studs por unidad del modelo (0.2 -> ~51 studs de alto).
	Modelo original: "Black Mesa Gonarch Rig" (CC-BY-4.0) - NO DONT EAT ME CASEOH (Ferris wheel) / Sketchfab.
]]
local SCALE = 0.2
local V3 = Vector3.new
local CFn = CFrame.new

local PLATE_B64 = ""

local B64 = {}
do
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, #chars do B64[chars:byte(i)] = i - 1 end
end
local function b64decode(s)
	local out, n = {}, 0
	for i = 1, #s, 4 do
		local a, b, c, d = s:byte(i, i + 3)
		local v = (B64[a] or 0) * 262144 + (B64[b] or 0) * 4096 + (B64[c] or 0) * 64 + (B64[d] or 0)
		n = n + 1 out[n] = math.floor(v / 65536)
		if c and c ~= 61 then n = n + 1 out[n] = math.floor(v / 256) % 256 end
		if d and d ~= 61 then n = n + 1 out[n] = v % 256 end
	end
	return out
end

local BOXES = {}
do
	local pb = b64decode(PLATE_B64)
	local function s16(p)
		local v = pb[p] + pb[p + 1] * 256
		if v >= 32768 then v = v - 65536 end
		return v
	end
	local QS = 0.7072 / 32767
	for i = 0, #pb / 20 - 1 do
		local p = i * 20
		local sx, sy, sz = pb[p + 2] / 100, pb[p + 3] / 100, pb[p + 4] / 100
		local idx = pb[p + 14]
		local vals = { s16(p + 15) * QS, s16(p + 17) * QS, s16(p + 19) * QS }
		local q, k = { 0, 0, 0, 0 }, 0
		for jj = 0, 3 do
			if jj ~= idx then k = k + 1 q[jj + 1] = vals[k] end
		end
		q[idx + 1] = math.sqrt(math.max(0, 1 - vals[1] ^ 2 - vals[2] ^ 2 - vals[3] ^ 2))
		BOXES[#BOXES + 1] = {
			bone = pb[p + 1],
			size = V3(sx, sy, sz),
			r = pb[p + 5], g = pb[p + 6], b = pb[p + 7],
			off = CFn(s16(p + 8) * 0.01, s16(p + 10) * 0.01, s16(p + 12) * 0.01, q[1], q[2], q[3], q[4]),
		}
	end
end

local function gridOf(studs) return math.clamp(studs / 2.5, 0.04, 1) end
local function q100(v) return math.floor(v * 100 + 0.5) end
local function makeKey(gx, gy, gz, r, g, b)
	return q100(gx) .. "," .. q100(gy) .. "," .. q100(gz) .. "|" .. r .. "," .. g .. "," .. b
end
for _, b in ipairs(BOXES) do
	b.gx, b.gy, b.gz = gridOf(b.size.X), gridOf(b.size.Y), gridOf(b.size.Z)
	b.color = Color3.fromRGB(b.r, b.g, b.b)
	b.key = makeKey(b.gx, b.gy, b.gz, b.r, b.g, b.b)
end
print(("[Gonarch] %d SmallParts necesarias (SCALE %.2f)"):format(#BOXES, SCALE))
-- ===== END SHARED =====

