local restQ = {}
local restCF = {}
local restT = {}
for k = 1, NJ do
	restQ[k] = { JREST_Q[k * 4 - 3], JREST_Q[k * 4 - 2], JREST_Q[k * 4 - 1], JREST_Q[k * 4] }
	restCF[k] = CFn(0, 0, 0, restQ[k][1], restQ[k][2], restQ[k][3], restQ[k][4])
	restT[k] = V3(JREST_T[k * 3 - 2], JREST_T[k * 3 - 1], JREST_T[k * 3])
end

local function loadAnim(i)
	local meta = ANIMS[i]
	if meta.parsed then return meta.parsed end
	local b = b64decode(ANIM_DATA[i])
	local p, fw = 1, meta.fw
	local function rdf()
		local v
		if fw == 1 then v = b[p] p = p + 1 else v = b[p] + b[p + 1] * 256 p = p + 2 end
		return v
	end
	local function s16()
		local v = b[p] + b[p + 1] * 256 p = p + 2
		if v >= 32768 then v = v - 65536 end
		return v
	end
	local rot, tra = {}, {}
	for k = 1, NJ do
		local n = b[p] + b[p + 1] * 256 p = p + 2
		local tr = { n = n, c = 1, f = {}, qx = {}, qy = {}, qz = {}, qw = {} }
		for m = 1, n do
			tr.f[m] = rdf()
			local u = b[p] + b[p + 1] * 256 + b[p + 2] * 65536 + b[p + 3] * 16777216 p = p + 4
			local idx = math.floor(u / 1073741824)
			local a = (math.floor(u / 1048576) % 1024 - 512) / 511 * 0.70711
			local bb = (math.floor(u / 1024) % 1024 - 512) / 511 * 0.70711
			local cc = (u % 1024 - 512) / 511 * 0.70711
			local q, kk, vals = { 0, 0, 0, 0 }, 0, { a, bb, cc }
			for jj = 0, 3 do
				if jj ~= idx then kk = kk + 1 q[jj + 1] = vals[kk] end
			end
			q[idx + 1] = math.sqrt(math.max(0, 1 - a * a - bb * bb - cc * cc))
			tr.qx[m], tr.qy[m], tr.qz[m], tr.qw[m] = q[1], q[2], q[3], q[4]
		end
		rot[k] = tr
	end
	for t = 1, #TJ do
		local n = b[p] + b[p + 1] * 256 p = p + 2
		local tr = { n = n, c = 1, f = {}, x = {}, y = {}, z = {} }
		local sc = TJ[t][2] * SCALE
		for m = 1, n do
			tr.f[m] = rdf()
			tr.x[m] = s16() * sc tr.y[m] = s16() * sc tr.z[m] = s16() * sc
		end
		tra[t] = tr
	end
	meta.parsed = { rot = rot, tra = tra }
	return meta.parsed
end

local function segOf(tr, f)
	local n, fs = tr.n, tr.f
	local c = tr.c
	if c > n - 1 or fs[c] > f then c = 1 end
	while c < n - 1 and fs[c + 1] <= f do c = c + 1 end
	tr.c = c
	local f0, f1 = fs[c], fs[c + 1]
	local w = 0
	if f1 > f0 then w = math.clamp((f - f0) / (f1 - f0), 0, 1) end
	return c, w
end

local function evalRot(tr, f, k)
	local n = tr.n
	if n == 0 then return restCF[k] end
	if n == 1 then return CFn(0, 0, 0, tr.qx[1], tr.qy[1], tr.qz[1], tr.qw[1]) end
	local c, w = segOf(tr, f)
	local ax, ay, az, aw = tr.qx[c], tr.qy[c], tr.qz[c], tr.qw[c]
	local bx, by, bz, bw = tr.qx[c + 1], tr.qy[c + 1], tr.qz[c + 1], tr.qw[c + 1]
	if ax * bx + ay * by + az * bz + aw * bw < 0 then bx, by, bz, bw = -bx, -by, -bz, -bw end
	local x, y, z, ww = ax + (bx - ax) * w, ay + (by - ay) * w, az + (bz - az) * w, aw + (bw - aw) * w
	local m = math.sqrt(x * x + y * y + z * z + ww * ww)
	if m < 1e-9 then return restCF[k] end
	return CFn(0, 0, 0, x / m, y / m, z / m, ww / m)
end

local function evalVec(tr, f, def)
	local n = tr.n
	if n == 0 then return def end
	if n == 1 then return V3(tr.x[1], tr.y[1], tr.z[1]) end
	local c, w = segOf(tr, f)
	return V3(tr.x[c] + (tr.x[c + 1] - tr.x[c]) * w, tr.y[c] + (tr.y[c + 1] - tr.y[c]) * w, tr.z[c] + (tr.z[c + 1] - tr.z[c]) * w)
end

-- default de cada pista de traslacion
local TJDEF = {}
for t = 1, #TJ do TJDEF[t] = V3(TJ[t][3], TJ[t][4], TJ[t][5]) end

-- pose local (CFrame por hueso) de una animacion en el frame f
local function poseAt(anim, f, rootMotion, out)
	local data = loadAnim(anim)
	local T = {}
	local anchor
	for t = 1, #TJ do
		local k = TJ[t][1]
		local v = evalVec(data.tra[t], f, TJDEF[t])
		if t == 1 then
			anchor = v
			if not rootMotion then
				local v0 = evalVec(data.tra[1], 0, TJDEF[1])
				anchor = V3(v0.X, v0.Y, v.Z) -- en sitio: se quita el desplazamiento horizontal (eje Z del rig = vertical)
			end
			T[k] = anchor
		elseif TJ[t][6] == 1 then
			T[k] = anchor + v   -- huesos de nivel superior: relativos al ancla
		else
			T[k] = v
		end
	end
	for k = 1, NJ do
		local rc = evalRot(data.rot[k], f, k)
		out[k] = CFn(T[k] or restT[k]) * rc
	end
	return out
end

----------------------------------------------------------------------
-- BUSCAR Y EMPAREJAR LAS SMALLPARTS DEL AVION
----------------------------------------------------------------------
local function numv(m, n)
	local c = m:FindFirstChild("Configuration")
	local o = c and c:FindFirstChild(n)
	return o and tonumber(o.Value)
end

local slots = {}   -- { part = BasePart, box = BOXES[i] }
local function collect(anyOwner)
	local byKey = {}
	for _, bx in ipairs(BOXES) do
		local l = byKey[bx.key]
		if not l then l = {} byKey[bx.key] = l end
		l[#l + 1] = bx
	end
	local roots, seenRoot = {}, {}
	local nModels, nMatched = 0, 0
	local function scan(container)
		for _, m in ipairs(container:GetDescendants()) do
			if m.Name == "SmallPart" and m:IsA("Model") then
				local sp = m:FindFirstChild("SPart")
				if sp and sp:IsA("BasePart") and (CFG.PLANE_ROOT or anyOwner or m:FindFirstAncestor(lp.Name)) then
					nModels = nModels + 1
					local gx, gy, gz = numv(m, "Size X"), numv(m, "Size Y"), numv(m, "Size Z")
					if gx and gy and gz then
						local c = sp.Color
						local key = makeKey(gx, gy, gz, math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
						local l = byKey[key]
						if l and #l > 0 then
							local bx = table.remove(l)
							slots[#slots + 1] = { part = sp, box = bx, model = m }
							nMatched = nMatched + 1
							local r = CFG.PLANE_ROOT or m:FindFirstAncestor(lp.Name)
							if r and not seenRoot[r] then seenRoot[r] = true roots[#roots + 1] = r end
						end
					end
				end
			end
		end
	end
	scan(CFG.PLANE_ROOT or workspace)
	return roots, nModels, nMatched
end

