end
local S = { cur = IDLE, t = 0, speed = 1, paused = false, loop = ANIMS[IDLE].loop, rootMotion = false, follow = false, autoIdle = CFG.AUTO_IDLE, speedIdx = 2 }
local SPEEDS = { 0.5, 1, 1.5, 2 }
