local blendFrom, blendT = nil, 0
local localPose, lastPose = {}, {}

local function refreshUI()
	for i, b in pairs(animButtons) do
		b.BackgroundColor3 = (i == S.cur) and C_ON or C_BTN
	end
	bPlay.Text = S.paused and "Play" or "Pausa"
	bLoop.BackgroundColor3 = S.loop and C_ON or C_BTN
	bRoot.Text = "Raiz: " .. (S.rootMotion and "SI" or "NO")
	bRoot.BackgroundColor3 = S.rootMotion and C_ON or C_BTN
	bFollow.Text = "Seguir: " .. (S.follow and "SI" or "NO")
	bFollow.BackgroundColor3 = S.follow and C_ON or C_BTN
	bAuto.Text = "Auto-idle: " .. (S.autoIdle and "SI" or "NO")
	bAuto.BackgroundColor3 = S.autoIdle and C_ON or C_BTN
	bSpeed.Text = ("Vel %sx"):format(tostring(S.speed))
end

local function play(i)
	if i < 1 then i = #ANIMS elseif i > #ANIMS then i = 1 end
	if blendFrom == nil then blendFrom = {} end
	for k = 1, NJ do blendFrom[k] = lastPose[k] end
	blendT = (CFG.BLEND_TIME > 0 and lastPose[1]) and CFG.BLEND_TIME or 0
	S.cur, S.t = i, 0
	S.loop = ANIMS[i].loop
	refreshUI()
	local b = animButtons[i]
	if b and b.Parent and list.Visible then
		local y = b.AbsolutePosition.Y - list.AbsolutePosition.Y + list.CanvasPosition.Y
		if b.AbsolutePosition.Y < list.AbsolutePosition.Y or b.AbsolutePosition.Y + b.AbsoluteSize.Y > list.AbsolutePosition.Y + list.AbsoluteSize.Y then
			list.CanvasPosition = Vector2.new(0, math.max(0, y - 40))
		end
	end
end

for i, a in ipairs(ANIMS) do
