local function charInfo()
	local ch = lp.Character
	local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
	local hum = ch and ch:FindFirstChildOfClass("Humanoid")
	return hrp, hum
end
local function placeHere()
	local hrp, hum = charInfo()
	if not hrp then return end
	local look = hrp.CFrame.LookVector * Vector3.new(1, 0, 1)
	if look.Magnitude < 0.01 then look = Vector3.new(0, 0, -1) end
	look = look.Unit
	local ground = hrp.Position.Y - (hum and (hum.HipHeight + hrp.Size.Y / 2) or 3)
	local pos = Vector3.new(hrp.Position.X, ground + CFG.GROUND_OFFSET, hrp.Position.Z) + look * CFG.START_DISTANCE
	origin = CFrame.lookAt(pos, pos - look) -- mira hacia ti
end
bHere.Activated:Connect(placeHere)

----------------------------------------------------------------------
-- PIEZAS
----------------------------------------------------------------------
local parts, boneOf, offOf = {}, {}, {}
local cfs = {}
local function setup()
	status.Text = "Buscando piezas del avion..."
	local roots, nModels, nMatched = collect(false)
	if nMatched == 0 then
		slots = {}
		roots, nModels, nMatched = collect(true) -- fallback: cualquier SmallPart del mapa que coincida en tamaño+color
	end
	if nMatched == 0 then
		status.Text = ("No encontre piezas coincidentes (%d SmallParts vistas). Spawnea el avion pintado con el script 1."):format(nModels)
		warn("[Gonarch] " .. status.Text)
		return false
	end
	local set = {}
	for i, s in ipairs(slots) do
		parts[i], boneOf[i], offOf[i] = s.part, s.box.bone, s.box.off
		set[s.part] = true
	end
	if CFG.DISABLE_JOINTS then
		local rootsList = roots
		if #rootsList == 0 then rootsList = { workspace } end
		for _, r in ipairs(rootsList) do
			for _, d in ipairs(r:GetDescendants()) do
				if d:IsA("JointInstance") or d:IsA("WeldConstraint") then
					if set[d.Part0] or set[d.Part1] then pcall(function() d.Enabled = false end) end
				elseif d:IsA("Constraint") then
					local a0, a1 = d.Attachment0, d.Attachment1
					if (a0 and set[a0.Parent]) or (a1 and set[a1.Parent]) then pcall(function() d.Enabled = false end) end
				end
			end
		end
	end
	for _, p in ipairs(parts) do
		pcall(function()
			p.CanCollide = false
			p.CanTouch = false
			p.Massless = true
			p.Anchored = CFG.ANCHOR_PARTS
		end)
	end
	status.Text = ("Piezas emparejadas: %d / %d  (SmallParts vistas: %d)"):format(nMatched, #BOXES, nModels)
	print("[Gonarch] " .. status.Text)
	return true
end

if not setup() then
	-- la UI queda abierta para poder cerrarla / reintentar colocando el avion
end

----------------------------------------------------------------------
-- BUCLE PRINCIPAL
----------------------------------------------------------------------
placeHere()
if origin == CFrame.new() then origin = CFrame.new(0, 10, 0) end
play(IDLE)
local yawFollow = 0
local world = {}
local conn
local FACE = CFrame.Angles(0, math.pi + math.rad(CFG.FACE_YAW), 0) * CFrame.Angles(-math.pi / 2, 0, 0)
local function chooseLoco(speed)
	local want = "idle"
	if speed > 0.5 then want = (speed > 14) and "a_run_N" or "walk" end
	local cur = ANIMS[S.cur].name
	if cur ~= want then
		for i, a in ipairs(ANIMS) do if a.name == want then play(i) break end end
	end
end

conn = RunService.Heartbeat:Connect(function(dt)
	if #parts == 0 then return end
	-- seguir al jugador (el joystick tactil mueve tu avatar => la bestia lo sigue y cambia sola idle/walk/run)
	if S.follow then
		local hrp, hum = charInfo()
		if hrp then
			local ground = hrp.Position.Y - (hum and (hum.HipHeight + hrp.Size.Y / 2) or 3)
			local dir = hrp.CFrame.LookVector * Vector3.new(1, 0, 1)
			if dir.Magnitude > 0.01 then dir = dir.Unit else dir = Vector3.new(0, 0, -1) end
			local target = Vector3.new(hrp.Position.X, ground + CFG.GROUND_OFFSET, hrp.Position.Z) - dir * CFG.FOLLOW_DIST
			local cur = origin.Position
			local flat = Vector3.new(target.X - cur.X, 0, target.Z - cur.Z)
			local spd = 0
			if flat.Magnitude > 2 then
				local step = math.min(flat.Magnitude, math.max(6, flat.Magnitude * 2) * dt)
				spd = step / math.max(dt, 1e-3)
				local np = cur + flat.Unit * step
				origin = CFrame.lookAt(Vector3.new(np.X, target.Y, np.Z), Vector3.new(np.X, target.Y, np.Z) + flat.Unit)
			else
				origin = CFrame.new(Vector3.new(cur.X, target.Y, cur.Z)) * (origin - origin.Position)
			end
			chooseLoco(spd)
		end
	end
	local meta = ANIMS[S.cur]
	if not S.paused then
		S.t = S.t + dt * S.speed
		if S.t >= meta.dur then
			if S.loop then
				S.t = S.t % meta.dur
			else
				S.t = meta.dur
				if S.autoIdle and S.cur ~= IDLE and not S.follow then play(IDLE) end
			end
		end
	end
	local f = (S.t / meta.dur) * (meta.nf - 1)
	poseAt(S.cur, f, S.rootMotion, localPose)
	for k = 1, NJ do lastPose[k] = localPose[k] end
	if blendT > 0 and blendFrom and blendFrom[1] then
		blendT = blendT - dt
		local a = 1 - math.clamp(blendT / CFG.BLEND_TIME, 0, 1)
		for k = 1, NJ do localPose[k] = blendFrom[k]:Lerp(localPose[k], a) end
	end
	local base = origin * FACE
	world[0] = base
	for k = 1, NJ do
		local par = JPAR[k]
		world[k] = world[par] * localPose[k]
	end
	local n = #parts
	for i = 1, n do cfs[i] = world[boneOf[i]] * offOf[i] end
	local ok = pcall(function() workspace:BulkMoveTo(parts, cfs) end)
	if not ok then
		for i = 1, n do pcall(function() parts[i].CFrame = cfs[i] end) end
	end
	if CFG.ZERO_VELOCITY and not CFG.ANCHOR_PARTS then
		for i = 1, n do
			local p = parts[i]
			p.AssemblyLinearVelocity = Vector3.zero
			p.AssemblyAngularVelocity = Vector3.zero
		end
	end
	status.Text = ("%s  %.2f/%.2fs  piezas %d"):format(meta.name, S.t, meta.dur, n)
end)

keyConn = UIS.InputBegan:Connect(function(i, gp)
	if gp then return end
	if i.KeyCode == Enum.KeyCode.Q then play(S.cur - 1)
	elseif i.KeyCode == Enum.KeyCode.E then play(S.cur + 1)
	elseif i.KeyCode == Enum.KeyCode.P then S.paused = not S.paused refreshUI()
	elseif i.KeyCode == Enum.KeyCode.L then S.loop = not S.loop refreshUI() end
end)

bClose.Activated:Connect(function()
	if conn then conn:Disconnect() end
	if dragConn then dragConn:Disconnect() end
	if keyConn then keyConn:Disconnect() end
	gui:Destroy()
	getgenv().GonarchRunning = false
end)
refreshUI()
